import{z as n,x as i,o as e,c as d,q as A,j as B,D as E,d as s,s as l,S as o,b as t}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"建立保持时间","description":"","frontmatter":{"title":"建立保持时间","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/setup-hold.md","filePath":"cs/setup-hold.md","lastUpdated":1791413859000}'),p={name:"cs/setup-hold.md"};function F(_,a,D,c,h,u){const r=i("Mermaid");return e(),d("div",null,[a[2]||(a[2]=A('<h1 id="建立保持时间" tabindex="-1">建立保持时间 <a class="header-anchor" href="#建立保持时间" aria-label="Permalink to &quot;建立保持时间&quot;">​</a></h1><div class="epigraph"><p>数据必须在时钟边沿之前稳定一段建立时间，边沿之后再保持一段；否则触发器可能进入亚稳，Q 不是合法比特。</p><footer>—— 据 Harris and Harris, Digital Design and Computer Architecture 整理</footer></div><p>上一课<a href="/cs/flipflop-types">D / T / JK 对照</a>钉死了边沿 D 触发器当记忆。本课不重画主从结构，也不从器件噪声统计另起。缺口是：FF 不是「边沿一瞬间任意 D 都行」。它要求 D 在边沿前后各有一段稳定窗口——<strong>建立</strong> \\(t_{su}\\) 与<strong>保持</strong> \\(t_h\\)。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>组合块有 \\(t_{pd}\\)、\\(t_{cd}\\)。两级 FF 之间夹着组合。缺口是把窗口写成不等式：周期 \\(T\\) 须满足 \\(t_{cq}+t_{pd}+t_{su}\\le T\\)（另加时钟偏斜），否则建立失败，下一拍采样到未稳数据。保持：\\(t_{cd}+t_{hold\\_path}\\ge t_h+t_{skew}\\) 一类，污染太快会冲掉刚锁存的值。</p><p>本课只钉这两条。多周期路径、假路径是工具细节。亚稳若仍发生，解析时间概率衰减，后课跨时钟域才强调同步器。</p><p><span class="marginnote">数字实例：设触发器 \\(t_{cq}=0.2\\) ns、中间组合逻辑最坏 \\(t_{pd}=3.0\\) ns、\\(t_{su}=0.3\\) ns，代入不等式得 \\(T \\ge 3.5\\) ns，即该路径最高支撑约 \\(1/3.5\\text{ns} \\approx 286\\) MHz。想跑到 500 MHz，就得把组合逻辑砍短，而不是简单换个更贵的触发器。</span></p><h3 id="加周期不能修保持" tabindex="-1">加周期不能修保持 <a class="header-anchor" href="#加周期不能修保持" aria-label="Permalink to &quot;加周期不能修保持&quot;">​</a></h3><p>建立失败可以降频。保持失败与 \\(T\\) 无关，必须加延迟或改路径。把所有时序问题都「把时钟调慢」，保持违规会留下。</p><p><span class="marginnote">Harris 给出带 skew 的建立/保持不等式。时钟偏斜后课寄存器仍当理想，多域在<a href="/cs/clock-domain">时钟域</a>才展开。本课先承认 skew 一项。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>单周期同步：同一时钟的 FF 到 FF。最坏 \\(t_{pd}\\) 管建立，最好 \\(t_{cd}\\) 管保持。缓冲器可以修保持（加大 \\(t_{cd}\\)），但可能恶化建立。</p>',12)),(e(),B(o,null,{default:E(()=>[l(r,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20FF1%5B%22FF%20%E5%90%AF%E5%8A%A8%22%5D%20--%3E%20COM%5B%22%E7%BB%84%E5%90%88%20t_pd%20%2F%20t_cd%22%5D%0A%20%20COM%20--%3E%20FF2%5B%22FF%20%E9%87%87%E6%A0%B7%22%5D%0A%20%20FF2%20--%3E%20SU%5B%22%E5%BB%BA%E7%AB%8B%EF%BC%9AT%20%E8%B6%B3%E5%A4%9F%22%5D%0A%20%20FF2%20--%3E%20HD%5B%22%E4%BF%9D%E6%8C%81%EF%BC%9A%E6%B1%A1%E6%9F%93%E5%A4%9F%E6%85%A2%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[s(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=t("h2",{id:"机制",tabindex:"-1"},[s("机制 "),t("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=t("p",null,"后课单周期 CPU 的 \\(T\\) 由最长指令路径加 \\(t_{su}\\) 决定。流水线把路径切开，每级仍要满足本课不等式——那是体系结构课的叶子，本课只给尺子。毛刺若落在采样窗口外则无事；落在窗口内等于 D 在边沿抖动。",-1)),a[5]||(a[5]=t("p",null,[t("span",{class:"marginnote"},"直觉类比：建立时间像「红灯前提前刹车」——数据必须在时钟边沿到达前就稳定停下；保持时间像「绿灯亮起后别立刻起步」——边沿过去一小段窗口内还得稳住，否则新数据追尾冲掉刚锁存的旧值。两个窗口一个在边沿前、一个在边沿后，方向相反。")],-1)),(e(),B(o,null,{default:E(()=>[l(r,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20V%5B%22%E7%AD%BE%E6%A0%B8%E6%8A%A5%E5%91%8A%E5%87%BA%E7%8E%B0%E6%97%B6%E5%BA%8F%E8%BF%9D%E8%A7%84%22%5D%20--%3E%20Q%7B%22%E8%A2%AB%E4%BE%B5%E7%8A%AF%E7%9A%84%E6%98%AF%E5%93%AA%E4%B8%AA%E7%AA%97%E5%8F%A3%3F%22%7D%0A%20%20Q%20--%3E%7C%E5%BB%BA%E7%AB%8B%E7%AA%97%E5%8F%A3%7C%20SU%5B%22%E5%BB%BA%E7%AB%8B%E8%BF%9D%E8%A7%84%3A%20%E8%B7%AF%E5%BE%84%E5%A4%AA%E6%85%A2%22%5D%0A%20%20SU%20--%3E%20F1%5B%22%E9%99%8D%E9%A2%91%20%2F%20%E7%BC%A9%E7%9F%AD%E7%BB%84%E5%90%88%E9%80%BB%E8%BE%91%20%2F%20%E6%B5%81%E6%B0%B4%E5%88%87%E5%BC%80%22%5D%0A%20%20Q%20--%3E%7C%E4%BF%9D%E6%8C%81%E7%AA%97%E5%8F%A3%7C%20HD%5B%22%E4%BF%9D%E6%8C%81%E8%BF%9D%E8%A7%84%3A%20%E6%95%B0%E6%8D%AE%E6%9D%A5%E5%BE%97%E5%A4%AA%E5%BF%AB%22%5D%0A%20%20HD%20--%3E%20F2%5B%22%E5%8A%A0%E7%BC%93%E5%86%B2%E5%BB%B6%E8%BF%9F%20%2F%20%E9%87%8D%E6%8E%92%E8%B7%AF%E5%BE%84%22%5D%0A%20%20F2%20--%3E%20W%5B%22%E9%99%8D%E9%A2%91%E6%97%A0%E6%95%88%2C%20%E5%BF%85%E9%A1%BB%E6%94%B9%E7%A1%AC%E4%BB%B6%E8%B7%AF%E5%BE%84%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[s(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=A('<p><span class="marginnote">常见误区：初学者容易觉得 \\(t_{cd}\\)（最小传播延迟）越小越好；恰恰相反，它是保持约束的保护垫——污染传得太快才会冲掉刚写入的值，所以物理设计里反而要专门往保持关键路径上插缓冲器「拖时间」。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把时序签核工具的 SDC 写成教程，不分析锁相环抖动谱。异步输入必须按后课时钟域同步，本课不等式对它不成立。</p><p>后课默认：同步设计先满足建立与保持；周期由建立定下界，保持用路径延迟保证。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>建立约束决定最小周期；保持与周期无关。</li><li>\\(t_{pd}\\) 对建立，\\(t_{cd}\\) 对保持。</li><li>降频修不了保持违规。</li><li>出处：Harris and Harris。</li></ul>',6))])}const C=n(p,[["render",F]]);export{f as __pageData,C as default};
